{
  "item_id": "PRISMA_2020_1",
  "elements": [
    {
      "element_id": "prisma_2020_1_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Living systematic review and network meta-analysis.",
      "reason": "The document explicitly identifies the study as a living systematic review in the Design section; the title of the paper (document title) likewise includes 'living systematic review', indicating the report is a systematic review."
    },
    {
      "element_id": "prisma_2020_1_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "In this living systematic review and network meta-analysis we compare the effects of drug treatments for covid-19.",
      "reason": "This sentence states the main objective and specifies the population/condition (covid-19) and the intervention type (drug treatments), matching the information conveyed in the title."
    },
    {
      "element_id": "prisma_2020_1_e3",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Living systematic review and network meta-analysis.",
      "reason": "The phrase includes supplementary information about analysis method ('network meta-analysis') and update status ('living'), which are relevant supplementary details expected for the title."
    }
  ],
  "confidence": "80"
}

{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Despite global efforts to identify effective interventions for the prevention and treatment of covid-19, which have resulted in approximately 3000 trials completed or underway, 2 evidence for effective treatment remains limited.",
      "reason": "Text describes the current state of knowledge (large number of trials) and explicitly states that evidence for effective treatment remains limited, indicating important uncertainties."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_11",
      "quote": "Living systematic reviews deal with the main limitation of traditional reviews-that of providing an overview of the relevant evidence only at a specific time. 4 This is crucial in the context of covid-19, in which the best evidence is constantly changing. The ability of a living network meta-analysis to present a complete, broad, and updated view of the evidence makes it the best type of evidence synthesis to inform the development of practice recommendations.",
      "reason": "The authors explain why a living network meta-analysis is needed (to address rapidly changing evidence and inform practice recommendations), establishing the importance and need for conducting this review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "To date, we are aware of two other similar efforts to ours. 42 43 Our intention is different in that the results fully inform clinical decision makingfor the associated living guidance. 6 Wealsoinclude a more comprehensive search for the evidence and several differences in analytical methods, which we believe are best suited for this evidence.",
      "reason": "The authors acknowledge other similar systematic efforts and explain how and why the current review differs and is needed (different intention, more comprehensive search, different analytical methods)."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "Mounting evidence suggests that antivirals (such as molnupiravir and nirmatrelvir) are most effective in the early stages of covid-19 when patients have non-severe disease, whereas anti-inflammatories (such as corticosteroids) seem to be most effective in the later disease stages.",
      "reason": "For interventions (drugs), the authors briefly describe differential proposed mechanisms/timing of effectiveness (antivirals early, anti-inflammatories later), addressing mechanism of action relevant to intervention effects."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence in the provided material of a logic model or diagram showing hypothesised relationships between intervention components and outcomes; nothing in retrieved evidence indicates a logic model was considered."
    }
  ],
  "confidence": "90"
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PRESENT",
      "chunk_id": "text_2",
      "quote": "To compare the effects of treatments for coronavirus disease 2019 (covid-19).",
      "reason": "The abstract provides an explicit statement of the review objective: to compare the effects of treatments for covid-19, which directly states the review question/objective."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "Randomised clinical trials in which people with suspected, probable, or confirmed covid-19 were randomised to drug treatment or to standard care or placebo.",
      "reason": "For this intervention review, the planned comparisons are stated: the population is people with suspected, probable, or confirmed covid-19 and the intervention/comparator contrast is drug treatment versus standard care or placebo (i.e., P and I and C are specified)."
    }
  ],
  "confidence": 85
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_13",
      "quote": "We included randomised clinical trials in people with suspected, probable, or confirmed covid-19 that compared drugs for treatment against one another or against no intervention, placebo, or standard care. We included trials regardless of publication status (peer reviewed, in press, or preprint) or language. No restrictions were applied based on severity of illness or setting, and we included trials of Chinese medicines if the drug comprised one or more specific molecules with a defined molecular weight dosing. We excluded randomised trials evaluating vaccination, blood products and antibody-based antiviral therapies (such as virus-specific monoclonal antibodies), nutrition, traditional Chinese herbal or alternative medicines that include more than one molecule or a molecule without specific molecular weighted dosing, and non-drug supportive care interventions.",
      "reason": "Specifies study design (randomised clinical trials), population (people with suspected/probable/confirmed covid-19), eligible comparisons (drugs vs drugs/no intervention/placebo/standard care), settings and severity (no restrictions), and explicit exclusions (vaccination, blood products, antibody therapies, non-drug interventions, complex herbal medicines)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PARTIAL",
      "chunk_id": "text_13",
      "quote": "We included trials regardless of publication status (peer reviewed, in press, or preprint) or language.",
      "reason": "The manuscript explicitly states inclusion regardless of publication status and language, but does not specify other report characteristics such as dissemination year; therefore reporting of report-characteristic criteria is only partial."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No explicit distinction was reported between excluding studies because outcomes were not measured versus excluding because outcome results were not reported; available evidence mentions trials with 'no outcomes of interest' but does not distinguish the two reasons."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "For each outcome, interventions were classified in groups from the most to the least beneficial or harmful following GRADE guidance.",
      "reason": "The methods state how interventions were grouped for the syntheses (classification into groups/nodes according to benefit/harm per GRADE). Additional evidence (callout_2 and text_26) documents node decisions (eg, combining placebo and standard care into the same node)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "callout_2",
      "quote": "Many of the results for comparisons with sparse data were uninformative and were sometimes implausible. For that reason, we decided to report evidence on treatments for which at least 100 people were randomised or for which there were at least 20 events.",
      "reason": "Provides a clear rationale for the notable restriction (analyzing only treatments with >=100 randomized people or >=20 events) due to sparse, uninformative, or implausible results."
    }
  ],
  "confidence": 85
}

