      "reason": "Study registers and online repositories are named (e.g., ClinicalTrials.gov, preprint servers, and specific Chinese databases) and a date is given for stopping Chinese database searches, but specific date restrictions or coverage dates for each register/repository are not provided for all sources."
    },
    {
      "element_id": "prisma_2020_6_e4",
      "status": "PARTIAL",
      "chunk_id": "text_14",
      "quote": \"The database includes... WHO covid-19 website, CDC covid-19 website, Eurosurveillance, China CDC Weekly,... We perform daily searches from Monday to Friday in the World Health Organization (WHO) covid-19 database for eligible studies.\",
      "reason": "Websites and online sources are named (e.g., WHO covid-19 website, CDC covid-19 website) and the WHO covid-19 database search frequency is described, but URLs for these sites are not provided."
    },
    {
      "element_id": "prisma_2020_6_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence that organisations or manufacturers were contacted to identify studies is reported in the provided text."
    },
    {
      "element_id": "prisma_2020_6_e6",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not describe contacting any individuals (types of individuals) to identify studies in the provided evidence."
    },
    {
      "element_id": "prisma_2020_6_e7",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no information in the provided evidence specifying the types of reference lists examined."
    },
    {
      "element_id": "prisma_2020_6_e8",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The provided evidence does not report details of backward or forward citation searching (seed reports, citation index/platform, or search dates)."
    },
    {
      "element_id": "prisma_2020_6_e9",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not report consulting specific journals or conference proceedings with names, dates covered, or search methods in the provided text."
    }
  ],
  "confidence": "86"
}

